import { createHash } from "node:crypto";

const REPRODUCER_KINDS = new Set(["scenario", "route", "command-id"]);
const PASS_OUTCOMES = new Set(["success", "succeeded", "passed", "rejected", "cancelled", "canceled"]);
const FAIL_OUTCOMES = new Set(["failed", "failure", "fail"]);
const SENSITIVE_KEYS = new Set([
  "rawprompt",
  "prompt",
  "messages",
  "body",
  "authorization",
  "apikey",
  "headers"
]);
const SECRET_PATTERNS = [
  /\bsk-[A-Za-z0-9_-]{8,}/,
  /\bphc_[A-Za-z0-9_-]{8,}/,
  /\bghp_[A-Za-z0-9_-]{8,}/,
  /\bAKIA[0-9A-Z]{12,}\b/,
  /-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/
];

function assertPlainObject(value, name) {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new TypeError(`${name} must be an object`);
  }
}

function stableStringify(value) {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(stableStringify).join(",")}]`;
  return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${stableStringify(value[key])}`).join(",")}}`;
}

function sha256(value) {
  return createHash("sha256").update(value).digest("hex");
}

function findSensitivePath(value, path = "$", found = []) {
  if (typeof value === "string") {
    if (SECRET_PATTERNS.some((pattern) => pattern.test(value))) found.push(path);
    return found;
  }
  if (value === null || typeof value !== "object") return found;
  if (Array.isArray(value)) {
    value.forEach((item, index) => findSensitivePath(item, `${path}[${index}]`, found));
    return found;
  }
  for (const [key, item] of Object.entries(value)) {
    const normalized = key.toLowerCase().replace(/[-_]/g, "");
    if (SENSITIVE_KEYS.has(normalized)) found.push(`${path}.${key}`);
    findSensitivePath(item, `${path}.${key}`, found);
  }
  return found;
}

function normalizeAttempt(attempt) {
  if (typeof attempt === "number" && Number.isSafeInteger(attempt) && attempt >= 0) return attempt;
  if (typeof attempt === "string" && /^\d+$/.test(attempt)) return Number(attempt);
  throw new TypeError("selector.attempt must be a non-negative integer");
}

function normalizeRunId(runId) {
  if (typeof runId !== "string" || runId.length === 0 || runId.length > 256) {
    throw new TypeError("selector.runId must be a non-empty string of at most 256 characters");
  }
  return runId;
}

function validateReproducer(reproducer) {
  assertPlainObject(reproducer, "reproducer");
  if (!REPRODUCER_KINDS.has(reproducer.kind)) {
    throw new TypeError("reproducer.kind must be one of scenario, route, command-id");
  }
  const result = { kind: reproducer.kind };
  if (reproducer.kind === "scenario") {
    if (typeof reproducer.scenarioId !== "string" || !reproducer.scenarioId || reproducer.scenarioId.length > 256) {
      throw new TypeError("reproducer.scenarioId must be a non-empty string of at most 256 characters");
    }
    result.scenarioId = reproducer.scenarioId;
  } else if (reproducer.kind === "route") {
    if (typeof reproducer.route !== "string" || !reproducer.route.startsWith("/") || reproducer.route.length > 2048) {
      throw new TypeError("reproducer.route must be an absolute path of at most 2048 characters");
    }
    result.route = reproducer.route;
  } else {
    if (typeof reproducer.commandId !== "string" || !reproducer.commandId || reproducer.commandId.length > 256) {
      throw new TypeError("reproducer.commandId must be a non-empty string of at most 256 characters");
    }
    result.commandId = reproducer.commandId;
  }
  return result;
}

function outcomeOf(trace) {
  const outcome = trace.outcome ?? trace.status ?? trace.result;
  if (typeof outcome !== "string") throw new TypeError("trace.outcome must be a string");
  const normalized = outcome.toLowerCase();
  if (FAIL_OUTCOMES.has(normalized)) return "fail";
  if (PASS_OUTCOMES.has(normalized)) return "pass";
  throw new TypeError(`unsupported trace outcome: ${outcome}`);
}

function selectorFor(trace, requestedSelector) {
  const candidate = requestedSelector ?? {
    runId: trace.runId,
    attempt: trace.attempt
  };
  assertPlainObject(candidate, "selector");
  const selector = {
    runId: normalizeRunId(candidate.runId),
    attempt: normalizeAttempt(candidate.attempt)
  };
  if (trace.runId !== undefined && selector.runId !== trace.runId) {
    throw new TypeError("selector.runId does not match trace.runId");
  }
  if (trace.attempt !== undefined && selector.attempt !== normalizeAttempt(trace.attempt)) {
    throw new TypeError("selector.attempt does not match trace.attempt");
  }
  return selector;
}

function expectation(value) {
  return { expect: value, expected: value, status: value };
}

/**
 * Convert one already-redacted failure trace into a bounded replay sample.
 * The source trace is never copied into the resulting sample.
 */
export function traceToEvalSample(trace, options = {}) {
  assertPlainObject(trace, "trace");
  assertPlainObject(options, "options");

  const sensitivePaths = findSensitivePath(trace);
  if (sensitivePaths.length > 0) {
    const error = new Error("trace contains sensitive material and was rejected");
    error.code = "TRACE_NOT_REDACTED";
    error.paths = [...new Set(sensitivePaths)].sort();
    throw error;
  }

  const reproducer = validateReproducer(options.reproducer);
  const selector = selectorFor(trace, options.selector);
  const beforeExpectation = outcomeOf(trace);
  const sample = {
    schemaVersion: 1,
    kind: "eval-sample",
    selector,
    reproducer,
    before: {
      ...expectation(beforeExpectation),
      selector,
      reproducer
    },
    after: {
      ...expectation("pass"),
      selector,
      reproducer
    }
  };
  sample.digest = sha256(stableStringify(sample));
  return sample;
}

/**
 * Explicitly convert only the selected traces. Each rejected trace is reported
 * independently and no rejected trace is included in `samples`.
 */
export function traceToEvalSamples(traces, options = {}) {
  if (!Array.isArray(traces)) throw new TypeError("traces must be an array");
  assertPlainObject(options, "options");
  const selectedRunIds = options.runIds ?? options.selectedRunIds;
  let selected = null;
  if (selectedRunIds !== undefined) {
    if (!Array.isArray(selectedRunIds)) throw new TypeError("options.runIds must be an array");
    selected = new Set(selectedRunIds.map(normalizeRunId));
  }

  const samples = [];
  const rejected = [];
  for (const trace of traces) {
    assertPlainObject(trace, "trace");
    const runId = typeof trace.runId === "string" ? trace.runId : undefined;
    if (selected && (runId === undefined || !selected.has(runId))) continue;
    try {
      samples.push(traceToEvalSample(trace, options));
    } catch (error) {
      rejected.push({
        runId: runId ?? null,
        attempt: trace.attempt ?? null,
        code: error?.code ?? "TRACE_REJECTED",
        message: error instanceof Error ? error.message : String(error),
        paths: Array.isArray(error?.paths) ? error.paths : []
      });
    }
  }
  return { samples, rejected };
}

export const convertTraceToEvalSample = traceToEvalSample;
export const convertSelectedTracesToEvalSamples = traceToEvalSamples;
export const buildTraceToEvalSample = traceToEvalSample;
export const validateTraceRedaction = (trace) => {
  assertPlainObject(trace, "trace");
  const paths = [...new Set(findSensitivePath(trace))].sort();
  return { redacted: paths.length === 0, paths };
};

export const TRACE_TO_EVAL_SAMPLE_VERSION = 1;

export type TraceReproducer =
  | { kind: "scenario"; scenarioId: string }
  | { kind: "route"; route: string }
  | { kind: "command-id"; commandId: string };

export interface TraceSelector {
  runId: string;
  attempt: number;
}

export interface TraceToEvalSampleOptions {
  reproducer: TraceReproducer;
  selector?: TraceSelector;
}

export interface TraceOutcome {
  expect: "fail" | "pass";
  expected: "fail" | "pass";
  status: "fail" | "pass";
  selector: TraceSelector;
  reproducer: TraceReproducer;
}

export interface TraceToEvalSample {
  schemaVersion: 1;
  kind: "eval-sample";
  selector: TraceSelector;
  reproducer: TraceReproducer;
  before: TraceOutcome;
  after: TraceOutcome;
  digest: string;
}

export interface SelectedTraceToEvalSampleOptions extends TraceToEvalSampleOptions {
  runIds?: readonly string[];
  selectedRunIds?: readonly string[];
}

export interface RejectedTraceDiagnostic {
  runId: string | null;
  attempt: number | null;
  code: string;
  message: string;
  paths: string[];
}

export interface TraceToEvalSampleBatchResult {
  samples: TraceToEvalSample[];
  rejected: RejectedTraceDiagnostic[];
}

export function traceToEvalSample(
  trace: Record<string, unknown>,
  options: TraceToEvalSampleOptions
): TraceToEvalSample;

export function traceToEvalSamples(
  traces: readonly Record<string, unknown>[],
  options: SelectedTraceToEvalSampleOptions
): TraceToEvalSampleBatchResult;

export const convertTraceToEvalSample: typeof traceToEvalSample;
export const convertSelectedTracesToEvalSamples: typeof traceToEvalSamples;
export const buildTraceToEvalSample: typeof traceToEvalSample;
export function validateTraceRedaction(trace: Record<string, unknown>): {
  redacted: boolean;
  paths: string[];
};
export const TRACE_TO_EVAL_SAMPLE_VERSION: 1;

# G03 closure: explicit trace-to-evaluation-sample conversion

## Usage

```js
import {
  traceToEvalSample,
  traceToEvalSamples
} from "../../scripts/lib/trace-to-eval-sample.mjs";

const sample = traceToEvalSample(trace, {
  reproducer: { kind: "route", route: "/api/example" },
  selector: { runId: trace.runId, attempt: trace.attempt }
});

const result = traceToEvalSamples(traces, {
  runIds: ["run-selected-by-the-caller"],
  reproducer: { kind: "scenario", scenarioId: "named-scenario" }
});
```

The operation is deliberately library-only and explicitly triggered. It creates no timer, scheduled job, background daemon, or automation.

## Result semantics

A failed trace becomes one sample with `before.expect === "fail"` and `after.expect === "pass"`. A successful, rejected, or cancelled trace has `before.expect === "pass"` and `after.expect === "pass"`. The `selector` identifies the exact `runId` and attempt. The reproducer is limited to a named scenario, route, or command ID and is never executed as shell text.

The digest is SHA-256 of the canonical JSON representation of the sample without its digest field, allowing deterministic replay comparison. The digest detects accidental change but must not be treated as a secret or as proof of redaction.

## Leak prevention

The complete trace is scanned before conversion. Any raw prompt/messages/body, authorization/API-key/header material, common token prefixes, or private-key material rejects that trace. A rejected trace is omitted from `samples`; the batch result contains only a separate diagnostic with paths and a reason. The original trace remains owned by the caller and is neither modified nor deleted.

## Selection and operational boundaries

Callers supply the exact trace list and may further restrict it with `runIds`/`selectedRunIds` (for example, IDs selected from the most recent seven days). No background selection occurs. The converter does not execute commands, call routes, change approval or lock behavior, or alter product defaults.

## Verification checklist

- Run the clean candidate's focused tests, type checking, and scoped lint.
- Run harness validate and dry-run for the new task specification.
- Scan candidate outputs for credentials; expected result is zero matches.
- Read back `SHA256SUMS` and verify its entries.

