  if (trace.attempt !== undefined && selector.attempt !== normalizeAttempt(trace.attempt)) {
    throw new TypeError("selector.attempt does not match trace.attempt");
  }
  return selector;
}

function expectation(value) {
  return { expect: value, expected: value, status: value };
}

/**
 * Convert one already-redacted failure trace into a bounded replay sample.
 * The source trace is never copied into the resulting sample.
 */
export function traceToEvalSample(trace, options = {}) {
  assertPlainObject(trace, "trace");
  assertPlainObject(options, "options");

  const sensitivePaths = findSensitivePath(trace);
  if (sensitivePaths.length > 0) {
    const error = new Error("trace contains sensitive material and was rejected");
    error.code = "TRACE_NOT_REDACTED";
    error.paths = [...new Set(sensitivePaths)].sort();
    throw error;
  }

  const reproducer = validateReproducer(options.reproducer);
  const selector = selectorFor(trace, options.selector);
  const beforeExpectation = outcomeOf(trace);
  const sample = {
    schemaVersion: 1,
    kind: "eval-sample",
    selector,
    reproducer,
    before: {
      ...expectation(beforeExpectation),
      selector,
      reproducer
    },
    after: {
      ...expectation("pass"),
      selector,
      reproducer
    }
  };
  sample.digest = sha256(stableStringify(sample));
  return sample;
}

/**
 * Explicitly convert only the selected traces. Each rejected trace is reported
 * independently and no rejected trace is included in `samples`.
 */
export function traceToEvalSamples(traces, options = {}) {
  if (!Array.isArray(traces)) throw new TypeError("traces must be an array");
  assertPlainObject(options, "options");
  const selectedRunIds = options.runIds ?? options.selectedRunIds;
  let selected = null;
  if (selectedRunIds !== undefined) {
    if (!Array.isArray(selectedRunIds)) throw new TypeError("options.runIds must be an array");
    selected = new Set(selectedRunIds.map(normalizeRunId));
  }

  const samples = [];
  const rejected = [];
  for (const trace of traces) {
    assertPlainObject(trace, "trace");
    const runId = typeof trace.runId === "string" ? trace.runId : undefined;
    if (selected && (runId === undefined || !selected.has(runId))) continue;
    try {
      samples.push(traceToEvalSample(trace, options));
    } catch (error) {
      rejected.push({
        runId: runId ?? null,
        attempt: trace.attempt ?? null,
        code: error?.code ?? "TRACE_REJECTED",
        message: error instanceof Error ? error.message : String(error),
        paths: Array.isArray(error?.paths) ? error.paths : []
      });
    }
  }
  return { samples, rejected };
}

export const convertTraceToEvalSample = traceToEvalSample;
export const convertSelectedTracesToEvalSamples = traceToEvalSamples;
export const buildTraceToEvalSample = traceToEvalSample;
export const validateTraceRedaction = (trace) => {
  assertPlainObject(trace, "trace");
  const paths = [...new Set(findSensitivePath(trace))].sort();
  return { redacted: paths.length === 0, paths };
};

export const TRACE_TO_EVAL_SAMPLE_VERSION = 1;
